import json

# 정제 한 번 = (규칙 버전, 바꾼 칸의 전·후)를 기록하고, 결과는 '덮어쓰기'로만 만든다.
experts = {"e1": {"company": "(株)ビザスク", "title": "PM"},
           "e2": {"company": "VisasQ Inc.", "title": "Engineer"}}
canonical = {"(株)ビザスク": "c-001", "VisasQ Inc.": "c-001"}

def cleanse(rows, run_id, log):
    for eid, r in rows.items():
        new = canonical.get(r["company"], r.get("company_id"))
        if r.get("company_id") != new:
            log.append({"run": run_id, "id": eid, "before": r.get("company_id"), "after": new})
            r["company_id"] = new

def rollback(rows, run_id, log):
    for ch in reversed([c for c in log if c["run"] == run_id]):
        rows[ch["id"]]["company_id"] = ch["before"]

log = []
cleanse(experts, "r1", log); first = json.dumps(experts, ensure_ascii=False)
cleanse(experts, "r2", log); second = json.dumps(experts, ensure_ascii=False)
print("두 번 돌려도 같나:", first == second, "/ r2 가 바꾼 칸:", sum(c["run"] == "r2" for c in log))
rollback(experts, "r1", log)
print("r1 되돌린 뒤:", experts)

# 출력
# 두 번 돌려도 같나: True / r2 가 바꾼 칸: 0
# r1 되돌린 뒤: {'e1': {'company': '(株)ビザスク', 'title': 'PM', 'company_id': None}, 'e2': {'company': 'VisasQ Inc.', 'title': 'Engineer', 'company_id': None}}
